const item = $input.first().json;
if (item.duplicateCheckPassed !== true || item.qaPackagePreserved !== true) throw new Error('Draft delivery blocked: duplicate-check result or preserved QA package is missing.');
let raw = String(item.output || item.text || '').replace(/\r\n?/g, '\n').trim();
if (!raw) throw new Error('Draft delivery blocked: complete QA package was not preserved from the editorial QA node.');
const chatId = $('Telegram Trigger').first().json.message.chat.id;
const today = new Intl.DateTimeFormat('en-CA', {timeZone:'Africa/Lagos',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const fence = String.fromCharCode(96).repeat(3);
const markdownMatch = raw.match(new RegExp(fence + 'markdown\\n([\\s\\S]*?)' + fence));
const markdown = markdownMatch ? markdownMatch[1] : '';
const dateMatch = markdown.match(/^publishDate:\s*["']?(\d{4}-\d{2}-\d{2})["']?\s*$/m);
const dateValue = dateMatch ? dateMatch[1] : '';
const parsedDate = dateValue ? new Date(dateValue + 'T00:00:00Z') : null;
const validDate = !!dateValue && !Number.isNaN(parsedDate.getTime()) && parsedDate.toISOString().slice(0,10) === dateValue && dateValue === today;
if (!markdownMatch || !validDate) throw new Error('QA package blocked: QA-authored publishDate missing, invalid, or not today in Africa/Lagos (' + today + '). Article delivery and queue creation stopped.');
if (!raw.endsWith('END OF QA PACKAGE')) throw new Error('QA package incomplete: END OF QA PACKAGE marker missing. Article delivery and queue creation stopped.');
const start = raw.indexOf('EDITORIAL QA RESULT');
const source = (start >= 0 ? raw.slice(start) : raw).trim();
const esc = s => s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
function inline(s) {
 let out = esc(s);
 const code = [];
 const tick = String.fromCharCode(96);
 out = out.replace(new RegExp(tick+'([^'+tick+']+)'+tick,'g'),(_,value)=>{const key='\u0000C'+code.length+'\u0000';code.push('<code>'+value+'</code>');return key;});
 out = out.replace(/\[([^\]]+)\]\((https:\/\/[^)\s]+)\)/g,'<a href="$2">$1</a>');
 out = out.replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/__(.+?)__/g,'<b>$1</b>').replace(/(^|[^*])\*([^*\n]+)\*/g,'$1<i>$2</i>').replace(/~~(.+?)~~/g,'<s>$1</s>');
 return out.replace(/\u0000C(\d+)\u0000/g,(_,i)=>code[Number(i)]);
}
function blockHtml(block) {
 const lines=block.split('\n');
 if (/^#{1,6}\s+/.test(block)) return '<b>'+inline(block.replace(/^#{1,6}\s+/,''))+'</b>';
 if (lines.every(x=>/^\s*[-*]\s+/.test(x))) return lines.map(x=>'• '+inline(x.replace(/^\s*[-*]\s+/,''))).join('\n');
 if (lines.every(x=>/^\s*\d+[.)]\s+/.test(x))) return lines.map(x=>inline(x.replace(/^\s*(\d+)[.)]\s/,'$1. '))).join('\n');
 if (lines.every(x=>/^\s*>/.test(x))) return '<blockquote>'+lines.map(x=>inline(x.replace(/^\s*>\s?/,''))).join('\n')+'</blockquote>';
 if (lines.length && lines.every(x=>/^\s*\|/.test(x))) {
  const rows=lines.filter(x=>!(/^\s*\|[\s:|-]+\|\s*$/).test(x));
  if(rows.length>1){const heads=rows[0].split('|').slice(1,-1).map(x=>x.trim());return rows.slice(1).map(row=>row.split('|').slice(1,-1).map((cell,i)=>(heads[i]?'<b>'+inline(heads[i])+':</b> ':'')+inline(cell.trim())).join(' — ')).join('\n');}
 }
 if (/^---+$/.test(block.trim()) || /^\*\*\*+$/.test(block.trim())) return '━━━━━━━━━━';
 return lines.map(inline).join('\n');
}
const blocks=source.split(/\n{2,}/).filter(x=>x.trim()).map(blockHtml);
const MAX=3200,chunks=[];let current='';
for(const block of blocks){
 if(block.length>MAX){if(current){chunks.push(current);current='';}const plain=block.replace(/<[^>]*>/g,'');let part='';for(const word of plain.split(/\s+/)){const next=part?part+' '+word:word;if(next.length>MAX&&part){chunks.push(esc(part));part=word;}else part=next;}if(part)chunks.push(esc(part));continue;}
 const candidate=current?current+'\n\n'+block:block;
 if(candidate.length<=MAX)current=candidate;else{if(current)chunks.push(current);current=block;}
}
if(current)chunks.push(current);if(!chunks.length)chunks.push('No QA content was returned.');
return chunks.map((part,i)=>({json:{chatId,text:'<b>Prismbyte QA — part '+(i+1)+'/'+chunks.length+'</b>\n\n'+part}}));

