const item = $input.first().json;
const today = new Intl.DateTimeFormat('en-CA', {timeZone:'Africa/Lagos', year:'numeric', month:'2-digit', day:'2-digit'}).format(new Date());
const source = String(item.output || item.text || '');
return [{json:{...item, output:'CURRENT SITE DATE (Africa/Lagos): ' + today + '\nThe final Astro frontmatter publishDate must equal this exact date. Correct it in the canonical article or set HOLD.\n\n' + source}}];

const item = $input.first().json;
const raw = String(item.output || item.text || '').replace(/\r\n?/g, '\n').trim();
const today = new Intl.DateTimeFormat('en-CA', {timeZone:'Africa/Lagos',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const marker = String.fromCharCode(96).repeat(3) + 'markdown';
const fence = String.fromCharCode(96).repeat(3);
const start = raw.indexOf(marker);
const contentStart = start >= 0 ? raw.indexOf('\n', start + marker.length) + 1 : -1;
const end = contentStart > 0 ? raw.indexOf(fence, contentStart) : -1;
const article = end > contentStart ? raw.slice(contentStart, end) : '';
const fmStart = article.startsWith('---\n') ? 4 : -1;
const fmEnd = fmStart >= 0 ? article.indexOf('\n---', fmStart) : -1;
const fm = fmEnd > fmStart ? article.slice(fmStart, fmEnd) : '';
const dateLine = fm.split('\n').find(line => /^publishDate:\s*/.test(line)) || '';
const date = dateLine.replace(/^publishDate:\s*/,'').trim().replace(/^["']|["']$/g,'');
const parsed = date ? new Date(date + 'T00:00:00Z') : null;
const validDate = !!date && !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0,10) === date && date === today;
const draftTrue = /^draft:\s*true\s*$/m.test(fm);
const header = raw.slice(0, Math.max(0, raw.indexOf('EDITORIAL QA RESULT') + 300));
const status = header.includes('PASS WITH FLAGS') ? 'PASS WITH FLAGS' : header.includes('HOLD') ? 'HOLD' : /\bPASS\b/.test(header) ? 'PASS' : 'MISSING';
const complete = raw.endsWith('END OF QA PACKAGE');
const issues = [];
if (!article) issues.push('Canonical Markdown article block is missing.');
if (!fm) issues.push('Valid YAML frontmatter block is missing.');
if (!validDate) issues.push('publishDate does not match current Africa/Lagos date ' + today + '.');
if (!draftTrue) issues.push('Canonical article must contain draft: true.');
if (!complete) issues.push('Required END OF QA PACKAGE marker is missing.');
const sourceMatch = fm.match(/^sources:\s*\n((?:[ \t]+-[^\n]*\n?)*)/m);
const sourceUrls = sourceMatch ? [...sourceMatch[1].matchAll(/https:\/\/[^\s"'<>]+/g)].map(m=>m[0].replace(/[),.;]+$/g,'')) : [];
const sourceSectionMatch = raw.match(/##\s+(?:[A-E]\.\s*)?SOURCE VERIFICATION TABLE([\s\S]*?)(?=\n## |\n---\n)/i);
const sourceSection = sourceSectionMatch ? sourceSectionMatch[1] : '';
const sourceRows = sourceSection.split('\n').filter(line=>/^\s*\|/.test(line) && !/^\s*\|[\s:|-]+\|\s*$/.test(line));
if (!sourceUrls.length) issues.push('Frontmatter sources array is missing or empty.');
if (!sourceSection) issues.push('Required SOURCE VERIFICATION TABLE is missing.');
for (const url of sourceUrls) {
  const row = sourceRows.find(line=>line.includes(url));
  if (!row) issues.push('Source missing from verification table: ' + url);
  else {
    if (!/\bEXTRACTED\b/i.test(row) || /SEARCH\s+RESULT|SNIPPET|NOT\s+EXTRACTED|FAILED|UNVERIFIED/i.test(row)) issues.push('Source is not confirmed as actually extracted: ' + url);
    if (row.length < 90) issues.push('Source row lacks specific evidence/claim detail: ' + url);
  }
}
if (/SEARCH\s+RESULT\s+CONFIRMED|SEARCH\s+RESULT\s+ONLY|NOT\s+EXTRACTED/i.test(sourceSection)) issues.push('Search-result-only evidence is present in source audit.');
function auditSection(name) {
  const re = new RegExp('##\\s+(?:[A-E]\\.\\s*)?' + name + '\\s*([\\s\\S]*?)(?=\\n##\\s+|\\n---\\n|$)','i');
  const m = raw.match(re);
  return m ? m[1] : '';
}
function tableRows(section) {
  return section.split('\n').filter(line=>/^\s*\|/.test(line) && !/^\s*\|[\s:|-]+\|\s*$/.test(line)).slice(1);
}
const claimAudit = auditSection('MATERIAL CLAIM AUDIT');
const claimRows = tableRows(claimAudit);
if (!claimAudit) issues.push('Required MATERIAL CLAIM AUDIT is missing.');
if (claimRows.length < 4) issues.push('Material claim audit must contain at least four substantive claim rows.');
if (/UNRESOLVED|UNVERIFIED|UNSUPPORTED|NEEDS HUMAN VERIFICATION|NOT VERIFIED/i.test(claimAudit)) issues.push('Material claim audit contains unresolved or unsupported claims.');
const numericalAudit = auditSection('NUMERICAL AND COST AUDIT');
const numericalRows = tableRows(numericalAudit);
const hasNumbers = /[$€£₦]|\b\d[\d,]*(?:\.\d+)?\s*(?:%|per\s+(?:month|year|week)|million|billion|tokens|users|customers|requests|days|hours|words|models|integrations)\b/i.test(article);
if (!numericalAudit) issues.push('Required NUMERICAL AND COST AUDIT is missing.');
if (hasNumbers && numericalRows.length < 1) issues.push('Numerical/cost claims exist but no auditable calculation/evidence rows were supplied.');
if (hasNumbers && !/formula|calculation|assumption|input|output|not applicable/i.test(numericalAudit)) issues.push('Numerical audit lacks assumptions/formula or explicit applicability statement.');
if (/INCORRECT|UNVERIFIED|UNSUPPORTED|NEEDS HUMAN VERIFICATION|UNRESOLVED/i.test(numericalAudit)) issues.push('Numerical audit reports unresolved or incorrect calculations.');
const capabilityAudit = auditSection('PRODUCT CAPABILITY AND SCOPE AUDIT');
if (!capabilityAudit) issues.push('Required PRODUCT CAPABILITY AND SCOPE AUDIT is missing.');
if (/UNRESOLVED|UNVERIFIED|UNSUPPORTED|NEEDS HUMAN VERIFICATION/i.test(capabilityAudit)) issues.push('Product capability/scope audit contains unresolved claims.');
const consistencyAudit = auditSection('FINAL CONSISTENCY AUDIT');
if (!consistencyAudit || !/\bPASS\b/i.test(consistencyAudit)) issues.push('Final consistency audit is missing or does not explicitly pass.');
if (/CONTRADICTION FOUND|INCONSISTENT|NOT APPLIED|UNRESOLVED/i.test(consistencyAudit)) issues.push('Final consistency audit reports a contradiction or unapplied correction.');
const structurallyValid = !!article && !!fm && validDate && draftTrue && complete;
const auditPassed = sourceUrls.length > 0 && !!sourceSection && issues.length === 0;
const qaGatePassed = structurallyValid && auditPassed;
const reason = qaGatePassed ? '' : issues.join(' ');
return [{json:{...item,qaGatePassed,qaStatus:status,qaGateDate:date,qaGateToday:today,qaGateReason:reason,qaGateAudit:{sourceCount:sourceUrls.length,sourceRows:sourceRows.length,claimRows:claimRows.length,numericalRows:numericalRows.length,capabilityAuditPresent:!!capabilityAudit,consistencyAuditPresent:!!consistencyAudit,issues}}}];

const sentItems = $('Send Draft to Telegram').all();
const qa = $('Editorial QA — Verify Sources and Claims').first().json;
const raw = String(qa.output || qa.text || '').replace(/\r\n?/g, '\n').trim();
const topic = String($('Load Pending Draft').first().json.topic || '').trim();
const fence = String.fromCharCode(96).repeat(3);
const marker = fence + 'markdown';
const start = raw.indexOf(marker);
const contentStart = start >= 0 ? raw.indexOf('\n', start + marker.length) + 1 : -1;
const end = contentStart > 0 ? raw.indexOf(fence, contentStart) : -1;
const article = end > contentStart ? raw.slice(contentStart, end).trim() : '';
if (!article.startsWith('---\n')) throw new Error('Queue blocked: canonical article frontmatter is missing.');
const fmEnd = article.indexOf('\n---', 4);
if (fmEnd < 0) throw new Error('Queue blocked: frontmatter closing delimiter is missing.');
const frontmatter = article.slice(4, fmEnd);
if (!raw.endsWith('END OF QA PACKAGE')) throw new Error('Queue blocked: required END OF QA PACKAGE marker is missing.');
const today = new Intl.DateTimeFormat('en-CA', {timeZone:'Africa/Lagos',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const publishDateLine = frontmatter.split('\n').find(line => /^publishDate:\s*/.test(line)) || '';
const publishDate = publishDateLine.replace(/^publishDate:\s*/, '').trim().replace(/^["']|["']$/g, '');
const parsedPublishDate = publishDate ? new Date(publishDate + 'T00:00:00Z') : null;
const validPublishDate = !!publishDate && !Number.isNaN(parsedPublishDate.getTime()) && parsedPublishDate.toISOString().slice(0,10) === publishDate && publishDate === today;
if (!validPublishDate) throw new Error('Queue blocked: QA-authored publishDate is missing, invalid, or not today in Africa/Lagos (' + today + ').');
const titleLine = frontmatter.split('\n').find(line => line.startsWith('title:')) || '';
const title = titleLine.slice(6).trim().replace(/^["']|["']$/g, '');
if (!title) throw new Error('Queue blocked: article title is missing.');
const slug = title.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
if (!slug) throw new Error('Queue blocked: could not derive a safe article slug.');
const sourceLines = frontmatter.split('\n');
const sourceIndex = sourceLines.findIndex(line => line.trim() === 'sources:');
const sourceUrls = [];
if (sourceIndex >= 0) for (let i=sourceIndex+1;i<sourceLines.length;i++){const line=sourceLines[i];if(!/^\s+-\s+/.test(line))break;const url=line.replace(/^\s+-\s+/,'').trim().replace(/^["']|["']$/g,'');if(/^https:\/\//i.test(url))sourceUrls.push(url);}
const headerIndex = raw.indexOf('EDITORIAL QA RESULT');
