if (qaStatus === 'MISSING') throw new Error('Queue blocked: editorial QA status is missing or unrecognized.');
const messageIds = sentItems.map(item => item.json?.result?.message_id).filter(id => Number.isInteger(id));
if (!sentItems.length || messageIds.length !== sentItems.length) throw new Error('Queue blocked: Telegram did not confirm delivery of every article message.');
const articleId = 'PB-' + String($execution.id);
const eligible = qaStatus === 'PASS';
return [{json:{article_id:articleId,topic,slug,article_markdown:article,source_urls_json:JSON.stringify(sourceUrls),qa_status:qaStatus,qa_flags_json:JSON.stringify({status:qaStatus,autoPublishEligible:eligible,reason:eligible?null:'Only exact PASS is eligible for the 12-hour review window.'}),review_status:eligible?'awaiting_review_notice':'hold_qa_flags',telegram_delivery_status:'article_chunks_delivered',telegram_message_ids:JSON.stringify(messageIds),review_sent_at:null,deadline_at:null,decision_at:null,decision_source:null,publish_status:eligible?'awaiting_review_notice':'blocked_qa',published_commit:null,published_url:null,last_error:null}}];

const msg = $('Telegram Trigger').first().json.message || {};
