const chatId = msg.chat && msg.chat.id !== undefined ? String(msg.chat.id) : '';
const fromId = msg.from && msg.from.id !== undefined ? String(msg.from.id) : '';
const authorized = chatId === '7392605484' && fromId === '7392605484' && msg.chat.type === 'private';
const validArticleId = /^PB-[A-Za-z0-9_-]+$/.test(articleId);
