else if (now >= Date.parse(row.deadline_at)) response = 'The 12-hour review window has expired. This decision was not recorded.';
else {
  allowed = true;
  nextReviewStatus = parsed.decision === 'approve' ? 'approved' : 'rejected';
  nextPublishStatus = parsed.decision === 'approve' ? 'approved_waiting_publish' : 'blocked_rejected';
  response = parsed.decision === 'approve'
