 article_id:record.article_id,
 review_status:eligible ? 'pending_review' : 'hold_qa_flags',
 telegram_delivery_status:'delivered',
 telegram_message_ids:JSON.stringify(ids),
 review_sent_at:sentAt.toISOString(),
 deadline_at:deadline ? deadline.toISOString() : null,
 publish_status:eligible ? 'pending_review' : 'blocked_qa'
}}];

const qa = $('Editorial QA — Verify Sources and Claims').first().json;
const raw = String(qa.output || qa.text || '').replace(/\r\n?/g, '\n').trim();
const fence = String.fromCharCode(96).repeat(3);
const marker = fence + 'markdown';
const start = raw.indexOf(marker);
