const titleLine = frontmatter.split('\n').find(line => line.startsWith('title:')) || '';
const title = titleLine.slice(6).trim().replace(/^["']|["']$/g, '');
const slug = title.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
if (!slug) throw new Error('Duplicate check blocked: safe slug could not be derived.');
const repoItems = $('Fetch Published Article Index — Queue Guard').all();
const published = repoItems.map(x => x.json).filter(f => f && f.type === 'file' && typeof f.name === 'string' && /\.mdx?$/i.test(f.name));
if (!published.length) throw new Error('Duplicate check blocked: GitHub article index returned no Markdown files; refusing fail-open.');
const queued = $('Get Existing Review Queue Slugs').all().map(x => x.json).filter(r => r && typeof r.slug === 'string' && r.slug.trim());
const publishedMatch = published.find(f => f.name.replace(/\.mdx?$/i,'') === slug);
const queueMatch = queued.find(r => String(r.slug).toLowerCase() === slug);
if (publishedMatch || queueMatch) throw new Error('Duplicate article slug blocked: ' + slug + (publishedMatch ? ' already exists in published GitHub articles.' : ' already exists in the review queue.'));
return [{json:{...qa,duplicateCheckPassed:true,qaPackagePreserved:true,slug,publishedArticleCount:published.length,reviewQueueRowsChecked:queued.length}}];

const row = $input.first()?.json || {};
const now = Date.now();
const deadline = Date.parse(row.deadline_at || '');
