Article ID: ' + $('Evaluate 12-Hour Timeout Eligibility').first().json.article_id + '
The 12-hour window expired with no decision. The timeout checks passed (QA PASS, confirmed delivery, valid deadline). It is now marked expired_waiting_publish. This is not yet a publication confirmation; the publishing/deployment gate must still pass.' }}

parameters.jsCode:
const row = $input.first()?.json || {};
const now = Date.now();
const nl = String.fromCharCode(10);
const today = new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Lagos',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const deadline = Date.parse(row.deadline_at || '');
const sentAt = Date.parse(row.review_sent_at || '');
const decidedAt = Date.parse(row.decision_at || '');
const ids = (() => { try { return JSON.parse(row.telegram_message_ids || '[]'); } catch { return []; } })();
let reason = '';
const qaFlags = (() => { try { return JSON.parse(row.qa_flags_json || '{}'); } catch { return {}; } })();
const approved = row.review_status === 'approved' && row.publish_status === 'approved_waiting_publish' && row.decision_source === 'telegram' && Number.isFinite(decidedAt) && Number.isFinite(deadline) && Number.isFinite(sentAt) && decidedAt >= sentAt && decidedAt <= deadline;
const timedOut = row.review_status === 'expired_no_response' && row.publish_status === 'expired_waiting_publish' && Number.isFinite(deadline) && Number.isFinite(sentAt) && now >= deadline;
if (row.article_id === 'PB-527') reason = 'PB-527 was independently rejected and is permanently blocked from publication.';
else if (!row.article_id || !row.slug || !row.article_markdown) reason = 'Missing article ID, slug, or article Markdown.';
else if (row.qa_status !== 'PASS' || qaFlags.status !== 'PASS' || qaFlags.autoPublishEligible !== true) reason = 'Editorial QA is not exactly PASS with an explicit autoPublishEligible=true flag.';
else if (!approved && !timedOut) reason = 'Review decision or timeout state is not an eligible publish state.';
else if (row.telegram_delivery_status !== 'delivered' || !Array.isArray(ids) || ids.length < 2 || !ids.every(Number.isInteger)) reason = 'Telegram delivery evidence is incomplete.';
else if (!Number.isFinite(sentAt) || !Number.isFinite(deadline) || deadline !== sentAt + 12*60*60*1000) reason = 'Review deadline is invalid or is not exactly 12 hours after delivery.';
else if (row.published_commit || ['published','deploy_pending'].includes(String(row.publish_status))) reason = 'Article already has a publication/deployment record.';
const article = String(row.article_markdown || '').replace(/\r\n?/g,nl).trim();
if (!reason && !article.startsWith('---' + nl)) reason = 'Article frontmatter is missing.';
const fmEnd = article.indexOf(nl + '---',4);
if (!reason && fmEnd < 0) reason = 'Article frontmatter closing delimiter is missing.';
const fm = fmEnd >= 0 ? article.slice(4,fmEnd) : '';
const getLine = (key) => {
  const re = new RegExp('^' + key + ':\\s*');
  const line = fm.split(nl).find(value => re.test(value)) || '';
  return line.replace(re,'').trim().replace(/^["']|["']$/g,'');
};
const title = getLine('title');
const description = getLine('description');
const publishDate = getLine('publishDate');
const category = getLine('category').replace(/^["']|["']$/g,'');
const draftLine = fm.split(nl).find(line => /^draft:\s*/.test(line)) || '';
const slugFromTitle = title.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
if (!reason && (!title || !description || !publishDate || !['ai-saas','automation','troubleshooting'].includes(category))) reason = 'Required Astro article frontmatter is incomplete or category is invalid.';
if (!reason && publishDate !== today) reason = 'Article publishDate is not today in Africa/Lagos ('+today+'); stale articles are held.';
if (!reason && draftLine !== 'draft: true') reason = 'QA article must remain draft:true until the guarded publication step.';
if (!reason && slugFromTitle !== row.slug) reason = 'Queue slug does not match the article title.';
if (!reason && !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(row.slug)) reason = 'Slug contains unsupported characters.';
const publishMarkdown = !reason ? article.replace(/^draft:\s*true\s*$/m,'draft: false') : '';
if (!reason && publishMarkdown === article) reason = 'Could not safely switch the article from draft:true to draft:false.';
return [{json:{article_id:row.article_id || '',slug:row.slug || '',title,article_markdown:article,publish_markdown:publishMarkdown,publishEligible:!reason,reason,review_status:row.review_status || '',qa_status:row.qa_status || '',publish_status:row.publish_status || ''}}];

const record = $('Validate Article for Publication').first().json;
const rows = $input.all().map(item => item.json || {});
const names = rows.map(row => row.name).filter(name => typeof name === 'string');
const validListing = rows.length > 0 && names.length === rows.length;
const duplicate = names.some(name => name === record.slug + '.md' || name === record.slug + '.mdx');
return [{json:{...record,slugAvailable:validListing && !duplicate,duplicate,listingValid:validListing,reason:!validListing?'GitHub article index could not be verified; publication blocked.':duplicate?'An article with this slug already exists in GitHub.': ''}}];

const body = $input.first()?.json || {};
const sha = $('Create Article Markdown on Main').first().json.commit.sha;
const slug = $('Validate Article for Publication').first().json.slug;
const articleId = $('Validate Article for Publication').first().json.article_id;
const data = $getWorkflowStaticData('global');
const key = 'prismbyte_deploy_poll_' + sha;
data[key] = Number(data[key] || 0) + 1;
const attempt = data[key];
const runs = Array.isArray(body.workflow_runs) ? body.workflow_runs : [];
const run = runs.find(item => item.head_sha === sha && item.name === 'Prismbyte — Build and Deploy to Cloudflare');
let state = 'pending';
let reason = 'The matching GitHub Actions deployment run has not appeared yet.';
if (run?.status === 'completed') {
  if (run.conclusion === 'success') { state = 'success'; reason = 'GitHub Actions build and Cloudflare deployment completed successfully.'; }
  else { state = 'failed'; reason = 'GitHub Actions deployment completed with conclusion: ' + String(run.conclusion || 'unknown') + '.'; }
} else if (run) reason = 'GitHub Actions deployment is still ' + String(run.status || 'in progress') + '.';
const pollAgain = state === 'pending' && attempt < 10;
if (state !== 'pending' || !pollAgain) delete data[key];
return [{json:{article_id:articleId,slug,commit_sha:sha,attempt,state,reason,pollAgain,deploymentSucceeded:state === 'success',deploymentFailed:state === 'failed',published_url:'https://prismbyte.site/blog/' + slug + '/'}}];

