parameters.jsCode:
const response = $input.first()?.json || {};
const deployment = $('Evaluate Cloudflare Deployment Result').first().json;
const statusCode = Number(response.statusCode || 0);
const body = String(response.body || response.data || '');
const canonicalPath = '/blog/' + deployment.slug + '/';
const liveVerified = statusCode === 200 && body.includes(canonicalPath);
const state = liveVerified ? 'success' : (statusCode >= 500 ? 'failed' : 'pending');
const reason = liveVerified ? 'The public article URL returned HTTP 200 and the expected canonical path.' : 'Live article URL verification did not pass (HTTP ' + String(statusCode || 'unknown') + '); the article will not be marked published.';
return [{json:{...deployment,liveVerified,state,reason}}];

